with scored as (select *, row_number() over w_ordered as seq_no, row_number() over w_grp as row_seq, dense_rank() over (partition by customer_id order by discount desc nulls first) as discount_dense_rank, last_value(shipping_fee) ignore nulls over (order by order_date, id rows between unbounded preceding and current row) as last_known_shipping_fee, lead(amount, 2) over w_running as next_amount from orders window w_ordered as (partition by customer_id order by amount, id), w_grp as (partition by customer_id order by discount, id), w_running as (partition by status order by discount, id)) select case when next_amount >= 1290 then 'LARGE' else 'SMALL' end as next_amount_tier, size(collect_set(channel)) as num_channels, count(*) filter (where status = 'PENDING') as pending_rows, round(sum(last_known_shipping_fee) / nullif(count(case when channel = 'partner' then 1 end), 0), 2) as last_known_shipping_fee_per_partner, size(collect_set(status)) as num_status, count(case when status = 'RETURNED' then 1 end) as returned_count, approx_percentile(seq_no, 0.95) as seq_no_p95 from scored group by case when next_amount >= 1290 then 'LARGE' else 'SMALL' end order by returned_count desc nulls last;
